fn.ToInteger = (e, defa) => {
    const re = /^[0-9\b]+$/;
    if (!fn.IsNullValue(e) && re.test(e)) {
        return parseInt(e);
    }
    return !fn.IsNullValue(defa) ? defa : -1;
};

fn.ToFloat = (e, defa) => {
    const re = /^[0-9\b]+$/;
    if (!fn.IsNullValue(e)) {
        let tmp = parseInt(e.toString().replace(".", ""));
        if (re.test(tmp)) {
            return parseFloat(e);
        }
    }
    return !fn.IsNullValue(defa) ? defa : -1;
};

fn.ToFixed = (e, num) => {
    const re = /^[0-9\b]+$/;
    if (!fn.IsNullValue(e)) {
        let tmp = parseInt(e.toString().replace(".", ""));
        if (re.test(tmp)) {
            return parseFloat(e).toFixed(num);
        }
    }
    return "";
};

