function BuildObject(obj, orgPath, value, newPath) {
    let tmpPath = newPath;
    if (fn.IsNull(tmpPath)) {
        newPath = orgPath.slice();
    }
    let path = newPath[0];
    let tPath;
    if (isNaN(path)) {
        if (fn.IsNull(obj[path])) {
            if (newPath.length > 1 && !isNaN(newPath[1])) {
                obj[path] = [];
                tPath = obj[path];
                newPath.shift();
            } else {
                if (Array.isArray(obj)) {
                    let idx = obj.push({ [path]: {} });
                    tPath = obj[idx - 1][path];
                    // Added 06:23 PM
                    obj = obj[idx - 1];
                } else {
                    obj[path] = {};
                    tPath = obj[path];
                    // Added 06:23 PM
                    //obj = obj[path];
                }
            }
        } else {
            tPath = obj[path];
            if (newPath.length > 1 && !isNaN(newPath[1])) {
                if (tPath.length > parseInt(newPath[1])) {
                    tPath = tPath[parseInt(newPath[1])];
                } else {
                    obj[path].push({});
                    tPath = obj[path];
                    tPath = tPath[parseInt(newPath[1])];
                }
                newPath.shift();
            }
        }
    }
    newPath.shift();
    if (newPath.length > 0) {
        BuildObject(tPath, orgPath, value, newPath);
    } else {
        obj[path] = value;
    }
}

