fn.ToJsonObject = (path, value) => {
    let strips = path.split(".");
    let _field = "";
    for (let i = 0; i < strips.length; i++) {
        if (i === strips.length - 1) {
            _field = `${_field}{"${strips[i]}":"${value}"${"}".repeat(
                strips.length - 1
            )}`;
        } else {
            _field = _field === "" ? `"${strips[i]}":` : `${_field}{"${strips[i]}":`;
        }
    }
    return JSON.parse(`{${_field}}`);
};

